# Content for the free money guides. Each guide = steps with copyable Claude prompts + an "agent" setup.
G = {}
G["credit"] = dict(
 paid=False,
 kw="CREDIT", title="Fix your credit report yourself", sub="Find errors on your credit reports and dispute them, with Claude doing the heavy lifting. No credit repair company needed.",
 time="About 30 minutes", need="Your 3 credit reports (free) and Claude",
 why="Errors on credit reports are common, and an error can raise what you pay for loans, cards, insurance and even apartments. You have the legal right to dispute anything that's wrong, for free.",
 steps=[
  ("Get all 3 reports, free", "Go to AnnualCreditReport.com, the only official free site. You can pull your Equifax, Experian and TransUnion reports every week at no cost. Download each one as a PDF. Reports don't show your score, and that's fine: the report is what you fix.", None, [("AnnualCreditReport.com","https://www.annualcreditreport.com")]),
  ("Black out the sensitive stuff", "Before uploading anywhere, cover your Social Security number and full account numbers. Claude doesn't need them to find errors. The last 4 digits are enough to tell accounts apart.", None, []),
  ("Have Claude audit all 3 reports", "Upload the three PDFs to Claude in one chat and paste this:", "I uploaded my credit reports from Equifax, Experian and TransUnion. Go through them carefully and make a table of anything that could be wrong or hurting me: accounts I might not recognize, wrong balances or limits, late payments, duplicate accounts or collections, items that look older than 7 years, paid or under $500 medical collections, and anything that's different between the three bureaus. For each one, tell me: the bureau, what looks wrong, why it matters, and what proof I would need. Then ask me which items are actually errors before suggesting what to dispute.", []),
  ("Dispute only what's actually wrong", "Go through Claude's table and confirm what's truly inaccurate. Then dispute it with the bureau that shows it. Online is fastest. The bureau generally has to investigate within 30 days (up to 45 in some cases). Have Claude write the dispute so it's clear and specific:", "Write a credit report dispute for [Equifax / Experian / TransUnion]. The item: [creditor name, last 4 digits, what it shows]. What is wrong: [your facts]. Proof I have: [statements, letters, payment confirmations]. Keep it short, factual and polite. Ask them to investigate and correct or delete the item under the Fair Credit Reporting Act, and list what I'm enclosing.", [("Equifax disputes","https://www.equifax.com/personal/credit-report-services/credit-dispute/"),("Experian disputes","https://www.experian.com/disputes/main.html"),("TransUnion disputes","https://www.transunion.com/credit-disputes/dispute-your-credit")]),
  ("Handle the true negatives the smart way", "Accurate negatives can't be disputed away, and nobody can legally remove them for you. But you can still ask. For a one time late payment on an account that's otherwise good, a goodwill letter sometimes works:", "Write a short goodwill letter to [creditor]. I've been a customer since [year]. I paid late in [month, year] because [honest reason]. I've paid on time since. Politely ask if they would consider removing the late payment from my credit reports as a goodwill gesture. No excuses, no demands.", []),
  ("Raise your score while disputes run", "Two things move your score most: paying on time, and how much of your card limits you're using. Set every card to autopay at least the minimum, and work balances down. Have Claude plan it:", "Here are my cards with balance, limit, APR and minimum: [list]. I can put $[amount] a month toward them. Make a month by month plan that lowers my credit utilization fastest and saves the most interest. Show the utilization on each card each month.", []),
  ("If a dispute goes nowhere", "If the bureau won't fix a clear error, you can file a complaint with the Consumer Financial Protection Bureau. Ask Claude to write it from your notes and proof.", None, [("CFPB complaint","https://www.consumerfinance.gov/complaint/")]),
 ],
 warn=["Only dispute information that is actually wrong. Disputing accurate items as false can backfire.","Credit repair companies can't legally charge you before doing the work, and they can't remove accurate information. Everything they do, you can do yourself for free.","Most negative items drop off on their own after about 7 years."],
 agent=dict(name="Credit Agent", what="A Claude Project that keeps your reports, your dispute log and the deadlines in one place. Each month you pull fresh reports and type 'monthly check'.",
  setup=["In Claude, create a new Project and name it Credit Agent.","Paste the instructions below into the Project's instructions.","Upload your redacted reports and Claude's audit table to the Project's files.","Once a month: pull fresh reports, drop them in, and type: monthly check."],
  instr="You are my Credit Agent. Your job: keep my credit reports accurate and help me raise my score. You have my redacted reports and my dispute log in the project files. Every time I say 'monthly check': compare the newest reports to the last ones, list anything new or changed, update the dispute log (item, bureau, date sent, 30 day deadline, status), tell me which disputes are overdue and draft follow ups, and give me my one most useful action this month. Only suggest disputing items I confirm are wrong. Keep answers short, with a table and a single next step."),
 sources=[("FTC: Credit repair, how to help yourself","https://consumer.ftc.gov/articles/disputing-errors-your-credit-reports"),("CFPB: credit reports and scores","https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/")],
)
G["bill"] = dict(
 kw="BILL", title="Cut a medical bill before you pay it", sub="Medical bills often have errors and there's often help available. Here's how to check yours and ask the right questions, with Claude.",
 time="About 30 minutes, plus a phone call", need="The bill, your insurance's Explanation of Benefits (EOB), and Claude",
 why="A medical bill is a starting point, not a final answer. You can ask for the details, question errors, apply for financial assistance and set up a payment plan.",
 steps=[
  ("Don't pay the summary bill yet", "Call the billing office and ask for an itemized bill with every charge and its billing code. Also log into your insurance and download the Explanation of Benefits (EOB) for that visit.", None, []),
  ("Black out what Claude doesn't need", "Cover your member ID, date of birth and account numbers before uploading.", None, []),
  ("Have Claude audit the bill", "Upload the itemized bill and the EOB, then paste this:", "I uploaded an itemized medical bill and my insurance Explanation of Benefits for the same visit. Compare them line by line. Find: duplicate charges, services that look like they didn't happen or don't match the visit, charges insurance should have covered or adjusted, amounts that differ between the bill and the EOB, and anything I should ask about. Make a table: line item, amount, what looks wrong, the question to ask. Explain billing codes in plain English. Don't assume, flag what needs checking.", []),
  ("Ask about financial assistance", "Most nonprofit hospitals are required to have a written financial assistance policy, and many people qualify without knowing it. Have Claude prep the call:", "Write me a short, friendly phone script to call [hospital] billing. I want to: ask if they have a financial assistance or charity care program and how to apply, ask about the line items I flagged [paste list], and ask for a no interest payment plan if I still owe money. Include what to say if they say no, and a list of things to write down during the call (name, date, reference number).", []),
  ("Negotiate what's left", "If you'll pay some of it, ask for a discount for paying in full or a payment plan you can actually afford. Get any agreement in writing.", "Write a short email to [hospital or provider] billing. Account ending in [last 4]. After reviewing my itemized bill I'm requesting: corrections on [items], a review for financial assistance, and [a discount for paying in full / a payment plan of $X per month]. Ask them to confirm any agreement in writing.", []),
  ("Know the credit rules", "The three credit bureaus don't include paid medical collections or medical collections under $500 on credit reports, and new medical debt isn't reported for a year. If you see one of these on your report, you can dispute it.", None, [("AnnualCreditReport.com","https://www.annualcreditreport.com")]),
  ("Surprise bills", "Federal law protects you from many surprise out of network bills, like emergency care, and gives self pay patients the right to a good faith estimate before care.", None, [("CMS: No Surprises","https://www.cms.gov/nosurprises")]),
 ],
 warn=["Claude helps you find questions to ask. The billing office and your insurer have the final word, so confirm everything with them.","Don't ignore a bill while you're reviewing it. Call and tell them it's under review.","Never share full insurance or card numbers in a chat."],
 agent=dict(name="Bill Agent", what="A Claude Project that checks every medical bill against your insurance before you pay, and tracks every call.",
  setup=["Create a new Claude Project named Bill Agent.","Paste the instructions below.","Upload your insurance plan summary (deductible, copays, out of pocket max) to the Project's files.","Every new bill: upload the itemized bill and EOB and type: check this bill."],
  instr="You are my Bill Agent. When I say 'check this bill', compare the itemized bill to the EOB and my plan summary, list possible errors and questions in a table, tell me how much I should actually owe based on my plan, and write the call script and follow up email. Keep a log of every bill (provider, date, amount billed, amount owed, status, call notes). Never tell me to pay before the review is done. Keep it short and clear."),
 sources=[("CFPB: medical billing and collections","https://www.consumerfinance.gov/consumer-tools/debt-collection/"),("CMS: No Surprises Act","https://www.cms.gov/nosurprises")],
)
G["debt"] = dict(
 kw="DEBT", title="Lower your interest and get out of card debt", sub="Ask for a lower rate, then follow a payoff plan built around your real numbers. Claude writes the script and does the math.",
 time="About 20 minutes, plus a few calls", need="Your card statements and Claude",
 why="Card interest is one of the most expensive things in most budgets. A lower rate and the right payoff order can save real money and months of payments.",
 steps=[
  ("List every debt", "Grab your latest statements. Black out full account numbers, then upload them or type the numbers in:", "Here are my debts with balance, APR and minimum payment: [list, or see uploaded statements]. Put them in a clean table. Show the total I owe, the total minimums, and roughly how much interest I'm paying each month on each one.", []),
  ("Call and ask for a lower rate", "It doesn't always work, but the call takes a few minutes and some people get a lower rate just by asking, especially with a good payment history. Also ask if they have a hardship program. Let Claude write your script:", "Write me a confident, polite phone script to ask [card company] for a lower APR. Facts: customer since [year], I [have / haven't] paid on time, my current APR is [X]%. Include: the opening ask, what to say if they say no (ask for a supervisor, ask about a temporary rate or hardship program), and what to write down. Keep it natural, not pushy.", []),
  ("Pick your payoff order", "Avalanche pays the highest APR first and usually saves the most interest. Snowball pays the smallest balance first for quick wins. Claude can show you both with your numbers:", "Using my debts above and $[amount] a month total to pay them, show me two plans: avalanche (highest APR first) and snowball (smallest balance first). For each: the payoff month for every debt, total interest paid, and the debt free date. Then tell me the difference in plain English.", []),
  ("Find extra money for the plan", "Upload one or two months of bank statements (account numbers blacked out):", "Look through these statements and find money I could redirect to debt: subscriptions, repeat fees, things I'm paying for twice, and my biggest spending categories. Give me the top 5 changes with how much each frees up per month. Be realistic, not extreme.", []),
  ("Be careful with quick fixes", "Balance transfer cards usually charge a transfer fee and the low rate ends on a set date. Debt settlement companies can hurt your credit and charge big fees. If you're overwhelmed, a nonprofit credit counselor can help you look at a debt management plan.", None, [("NFCC nonprofit counseling","https://www.nfcc.org"),("FTC: debt relief scams","https://consumer.ftc.gov/articles/how-get-out-debt")]),
 ],
 warn=["This is education, not financial advice. Check the numbers on your actual statements.","Never pay anyone upfront to settle or erase your debt.","Keep paying at least the minimum on everything while you work the plan."],
 agent=dict(name="Debt Agent", what="A Claude Project that tracks every balance, keeps your payoff plan current and tells you exactly what to pay each month.",
  setup=["Create a new Claude Project named Debt Agent.","Paste the instructions below.","Add your debt table and chosen plan to the Project's files.","After each payday or statement: type your new balances and say: update my plan."],
  instr="You are my Debt Agent. You have my debts and my chosen payoff plan in the project files. When I say 'update my plan', take my new balances, recalculate the plan, tell me exactly how much to pay on each debt this month, show progress (total paid off, interest saved vs minimums, new debt free date), and flag anything off track. Celebrate each debt that hits zero. Keep it short: a table, the payment list, one sentence of encouragement."),
 sources=[("CFPB: debt and credit tools","https://www.consumerfinance.gov/consumer-tools/credit-cards/"),("FTC: how to get out of debt","https://consumer.ftc.gov/articles/how-get-out-debt")],
)
G["subs"] = dict(
 kw="SUBS", bundle=False, title="Find and kill forgotten subscriptions", sub="Most people pay for at least one subscription they forgot about. Here's how to find every one in 10 minutes with Claude, and cancel the right way.",
 time="About 15 minutes", need="2 to 3 months of bank and card statements, and Claude",
 why="Subscriptions are built to be forgotten: small amounts, automatic charges, free trials that quietly convert. Ten minutes with your statements usually finds money you can keep every single month.",
 steps=[
  ("Download 3 months of statements", "Log into your bank and every credit card and download the last 3 months as PDF or CSV. Three months catches charges that only show up every other month or every quarter. Don't forget PayPal, Apple and Google, since app subscriptions often hide there.", None, [("Apple: see your subscriptions","https://support.apple.com/en-us/118428"),("Google Play subscriptions","https://play.google.com/store/account/subscriptions")]),
  ("Black out the sensitive stuff", "Cover full account and card numbers before uploading. Claude only needs the merchant names, dates and amounts.", None, []),
  ("Have Claude find every recurring charge", "Upload all the statements to one Claude chat and paste this:", "I uploaded 3 months of my bank and card statements. Find every recurring or repeating charge, including ones with slightly different names or amounts, annual renewals, app store charges and free trials that turned paid. Make a table: merchant, what it probably is, amount, how often, yearly cost, and which card it's on. Then sort by yearly cost and give me the total per month and per year. Ask me which ones I actually use before suggesting anything.", []),
  ("Decide: keep, cut or downgrade", "Go down the list and mark each one. For anything you're unsure about, ask Claude for a cheaper plan or a free alternative:", "Here's what I decided: [paste list with keep / cut / unsure]. For the unsure ones, tell me if there's a cheaper tier, an annual plan that saves money, a free alternative, or something I'm paying for twice (like two music or two cloud storage plans). Then show me my new monthly and yearly total and how much I save.", []),
  ("Cancel the right way", "Cancel through the same place you signed up: the app store, the website or the company's account page. Take a screenshot of the cancellation confirmation. If a company makes it hard, have Claude write a clear written request:", "Write a short cancellation request to [company] for my [plan] subscription under the email [your email]. Ask them to cancel effective today, stop all future charges, and confirm the cancellation in writing. Keep it polite and firm, and add one line asking for a refund of any charge made after today.", []),
  ("If they keep charging you", "If you're charged after canceling, first ask the company for a refund with your screenshot. If that fails, dispute the charge with your card. For credit cards, federal law gives you 60 days from the statement date to dispute a billing error in writing.", None, [("CFPB: how to dispute a charge","https://www.consumerfinance.gov/ask-cfpb/how-do-i-dispute-a-charge-on-my-credit-card-bill-en-61/")]),
 ],
 warn=["The federal 'click to cancel' rule was struck down in 2025, so cancellation rules depend on your state and the company. Always keep proof that you canceled.","Canceling your card doesn't cancel the subscription. Companies can still bill you or send it to collections. Cancel first.","Check annual plans before canceling. Some don't refund the rest of the year."],
 agent=dict(name="Subscription Agent", what="A Claude Project that checks your statements every month, flags any new or price-raised subscription, and writes the cancel message for you.",
  setup=["Create a new Claude Project named Subscription Agent.","Paste the instructions below.","Add a note to the Project with what you decided to keep.","Once a month: upload your newest statements and type: monthly sweep."],
  instr="You are my Subscription Agent. When I say 'monthly sweep', read the statements I upload, list every recurring charge, and compare it to my keep list. Flag: new subscriptions, price increases, free trials that turned paid, duplicates, and anything I said I canceled that is still charging. For each flag, write the cancel or refund message ready to send. End with my total per month and per year, and how much I saved since I started. Keep it short."),
 sources=[("CFPB: disputing a credit card charge","https://www.consumerfinance.gov/ask-cfpb/how-do-i-dispute-a-charge-on-my-credit-card-bill-en-61/"),("FTC: report a company that won't let you cancel","https://reportfraud.ftc.gov")],
)
G["refund"] = dict(
 kw="REFUND", bundle=False, title="Get your money back", sub="Canceled flights, double charges, things that never arrived. You often have a legal right to a refund. Here's how to claim it with Claude.",
 time="About 10 minutes per refund", need="The receipt or booking, any emails, and Claude",
 why="Companies don't always refund you automatically, even when they should. A clear, specific request that names your rights gets results far more often than an angry phone call.",
 steps=[
  ("Find your refunds", "Have Claude scan your recent statements and emails for money you may be owed:", "I uploaded my last 3 months of card statements. Find anything that could be refundable: duplicate charges, charges for things I canceled, orders that may not have arrived, canceled or changed flights, hotel or rental fees, price increases, and fees I didn't agree to. Make a table: merchant, date, amount, why it might be refundable, and what proof I should find. Ask me before assuming.", []),
  ("Flights: know the rule", "Under U.S. Department of Transportation rules, if an airline cancels your flight or makes a significant change and you don't accept the alternative, you're entitled to a cash refund, including taxes and fees, not just a voucher. Significant changes include departing or arriving 3+ hours off for domestic flights or 6+ hours for international. Refunds are due within 7 business days for card payments.", None, [("DOT: refunds","https://www.transportation.gov/airconsumer/refunds")]),
  ("Write a request that gets approved", "Paste your booking or receipt details and use this:", "Write a refund request to [company]. Order or booking number: [number]. What happened: [facts and dates]. What I want: a refund of $[amount] to my original payment method. If it applies, mention my rights [for flights: the DOT refund rule for canceled or significantly changed flights / for cards: my right to dispute billing errors]. Keep it short, specific and polite, list what I'm attaching, and give them 7 days to respond.", []),
  ("Escalate if they say no", "If the company refuses or ignores you, file a complaint. For airlines, file with DOT. For card charges, dispute with your card issuer within 60 days of the statement. Have Claude write it:", "Write a dispute for my card issuer. Charge: [merchant, date, amount]. What went wrong: [facts]. What I did to fix it with the merchant: [dates and responses]. Ask them to remove the charge as a billing error, and list the proof I'm attaching.", [("DOT: file an air travel complaint","https://www.transportation.gov/airconsumer/file-consumer-complaint"),("CFPB: submit a complaint","https://www.consumerfinance.gov/complaint/")]),
  ("Keep a paper trail", "Save every email, screenshot and reference number. Claude can turn your notes into a timeline in seconds, and a clean timeline is what wins disputes.", None, []),
 ],
 warn=["Claude helps you write the request. The company, the DOT or your card issuer decides the outcome.","Only dispute charges that are actually wrong. A dispute isn't a way to get out of a purchase you agreed to.","Debit cards have different and often weaker protections than credit cards. Act fast."],
 agent=dict(name="Refund Agent", what="A Claude Project that finds money you're owed, writes every refund request and dispute, and tracks each one until you're paid.",
  setup=["Create a new Claude Project named Refund Agent.","Paste the instructions below.","When something goes wrong, upload the receipt or booking and type: get my money back.","Once a month: upload your statements and type: refund scan."],
  instr="You are my Refund Agent. When I say 'get my money back', read what I upload, tell me if I likely have a right to a refund and why, then write the request ready to send. When I say 'refund scan', check my statements for duplicate charges, canceled services still billing, and fees I didn't agree to. Keep a log of every claim (company, amount, date sent, deadline, status) and remind me of the next step and any deadline, like the 60 day card dispute window. Never invent facts. Keep it short."),
 sources=[("DOT: airline refunds","https://www.transportation.gov/airconsumer/refunds"),("CFPB: disputing a charge","https://www.consumerfinance.gov/ask-cfpb/how-do-i-dispute-a-charge-on-my-credit-card-bill-en-61/")],
)
G["raise"] = dict(
 kw="RAISE", bundle=False, title="Ask for a raise and get it", sub="Use real pay data and Claude to build your case, practice the conversation, and know exactly what to say when they push back.",
 time="About 45 minutes", need="Your job title, location, a list of your wins, and Claude",
 why="Most raises go to people who ask with a clear case: what the market pays, what you've delivered, and a specific number. Claude helps you build all three and rehearse until it feels easy.",
 steps=[
  ("Get real pay data", "Look up your job on the Bureau of Labor Statistics wage data. It shows pay ranges (10th to 90th percentile) by job and by city. Then compare job posts for your role: in several states, including California, Colorado, New York and Washington, job ads must include a pay range.", None, [("BLS wage data by job and area","https://www.bls.gov/oes/"),("BLS occupation search","https://data.bls.gov/oes/")]),
  ("Turn your work into proof", "Dump everything you did this year into Claude, messy is fine:", "Here's everything I did at work this year: [paste notes, projects, emails, praise, numbers]. Turn it into 5 to 7 clear wins. For each one: what I did, the result, and the number that proves it (money saved or made, time saved, customers, growth). Ask me for any number you think is missing. Then rank them by what my manager cares about most.", []),
  ("Pick your number", "Give Claude your data and let it build the case:", "My role: [title] in [city]. My current pay: $[amount]. Market data I found: [BLS percentiles and job post ranges]. My wins: [paste]. Recommend a specific raise to ask for, with a reason it's fair, a number slightly above my target, and the lowest I should accept. Explain it in 3 sentences I can say out loud.", []),
  ("Write the ask and rehearse it", "Ask for a meeting on its own, not inside a regular check in. Then practice:", "Write a short message asking my manager for a 30 minute meeting to talk about my compensation. Then play my manager in a practice conversation. Push back realistically: no budget, wait until review season, you're paid fairly, what about a title instead. After each of my answers, coach me on what to say better. Keep it natural, not scripted.", []),
  ("If the answer is not now", "Don't leave empty handed. Ask what exactly you need to do to get there, and by when, and get it in writing. Have Claude write the follow up email the same day.", "Write a short follow up email to my manager after our pay conversation. Thank them, summarize what we agreed: [what they said], the goals I need to hit, and the date we'll revisit. Keep it positive and professional.", []),
 ],
 warn=["Pay data is a starting point. Your company, industry and experience change the number.","Never share confidential company information with any AI tool. Describe your wins in general terms if needed.","Be honest. Don't claim a competing offer you don't have."],
 agent=dict(name="Raise Agent", what="A Claude Project that tracks your wins all year, keeps your market pay data fresh, and preps you for every pay conversation.",
  setup=["Create a new Claude Project named Raise Agent.","Paste the instructions below.","Every Friday, type: win log, then paste what you did that week.","Before any review, type: prep my raise."],
  instr="You are my Raise Agent. When I say 'win log', turn my notes into clear wins with numbers and save them. When I say 'prep my raise', use my wins and the pay data I give you to recommend a specific number, write my talking points, and run a practice conversation as my manager with realistic pushback, coaching me after each answer. Keep my wins list ready to paste. Be honest when my case is weak and tell me what would make it stronger."),
 sources=[("BLS Occupational Employment and Wage Statistics","https://www.bls.gov/oes/")],
)
TT = dict(cat="TIKTOK × AI", bundle_link="tiktok-agents", bundle_txt="$10, or all 3 TikTok agents for $24.", bundle_btn="ALL 3 · $24")
G["video"] = dict(TT,
 kw="VIDEO", title="Make TikToks with AI that plans every edit and gets your posts scheduled", sub="Claude finds what works in your niche, writes the scripts, plans every cut and caption, and can schedule the posts if you connect a scheduler. You film and cut the clips.",
 time="About 1 hour for a full week of videos", need="A phone, CapCut (free), and Claude",
 why="Most of the work in a TikTok isn't filming. It's the hook, the script, the cuts, the captions and posting at the right time. Claude does the thinking and writing, CapCut does the cutting, and a scheduler posts on time.",
 steps=[
  ("Find what's working in your niche", "Open TikTok, search your niche, and write down the first line (the hook) and topic of 10 recent videos (last 30 days) from accounts close to your size that got far more views than they have followers. Huge accounts teach the wrong lessons. Paste them into Claude:", "Here are the hooks and topics of 10 high view TikToks from the last 30 days in my niche [niche]: [paste]. Find the patterns: which hook styles repeat, which topics, how fast they get to the point, and what makes people comment. Then give me 10 video ideas for my account that use those patterns but say something new. My account is about [what you do] for [who].", []),
  ("Write a week of scripts in one go", "Pick your best 7 ideas and have Claude write them so they're ready to film:", "Write 7 TikTok scripts from these ideas: [paste]. Each one: a hook that works in the first 2 seconds, 3 short beats, and a clear ending (follow, comment a word, or a question). Under 30 seconds when spoken. Add the on screen text for each beat and one line on what to show. Write how I talk: [describe your voice]. No hype words.", []),
  ("Turn each script into an edit plan", "This is the part that makes AI your editor. Claude can't cut the video itself, but it tells you exactly where every cut, caption and sound goes:", "Turn this script into an edit plan for CapCut: [paste script]. Give me a shot list (what to film or which clip), where each cut goes in seconds, the text on screen and when it appears, where to zoom or add B roll, and the type of sound to use. Keep the first 2 seconds as strong as possible.", []),
  ("Edit fast in CapCut", "Film the shots, drop them in CapCut, cut where the plan says, and use Auto captions so the words appear on screen. Captions help people who watch in noisy places or with the sound off, and they make your video easier to find in TikTok search. For anything you sell, only use sounds from TikTok's or CapCut's commercial library. If you ever use AI to make realistic people, voices or scenes, turn on TikTok's AI generated content label.", None, [("CapCut","https://www.capcut.com"),("TikTok: AI generated content","https://support.tiktok.com/en/using-tiktok/creating-videos/ai-generated-content")]),
  ("Get the caption, hashtags and cover", "Put the words people would search for in your caption and on screen text, and say them out loud in the first few seconds: TikTok uses all three to show your video in search. Paste the final script and let Claude write the post:", "Write the TikTok post for this video: [paste script]. Give me a caption under 150 characters that adds to the video and includes the words people would search for, 4 relevant hashtags (no generic ones like #fyp), and 3 options for the cover text, max 5 words each.", []),
  ("Get it posted on time", "With a Creator or Business account, TikTok Studio in a browser lets you schedule videos up to 10 days ahead. A scheduler like Metricool lets you schedule from your phone, and if you connect Metricool to Claude, Claude can fill in the caption and time and schedule it: you upload the video, it does the rest. Metricool's free plan covers about 20 scheduled posts a month, so daily posting needs a paid plan or TikTok Studio. Schedulers usually can't add TikTok Shop product links or trending sounds, so post shoppable videos from the TikTok app.", None, [("TikTok Studio","https://www.tiktok.com/tiktokstudio"),("Metricool","https://metricool.com")]),
  ("Review every week and double down", "Once a week, paste your numbers so Claude tells you what to make more of:", "Here are my TikTok numbers from this week: [for each video: topic, hook, views, average watch time or % watched, likes, comments, shares, follows]. Tell me which hooks and topics are working, what to stop, and plan next week's 7 videos doubling down on the winner with one new test.", []),
 ],
 warn=["Claude plans and writes. Watch every video yourself before it goes out.","Label realistic AI generated content on TikTok. Never use AI to show a real person doing or saying something they didn't.","Don't repost other creators' videos or use music you don't have rights to in ads."],
 agent=dict(name="Video Agent", what="A Claude Project that knows your niche, your voice and your best videos, and every week hands you scripts, edit plans and ready to post captions.",
  setup=["Create a Claude Project named Video Agent.","Paste the instructions below.","Add a note with your niche, who you make videos for, how you talk, and your 3 best videos so far.","Every Sunday type: week plan. Before editing type: edit plan. Every Friday paste your numbers and type: review."],
  instr="You are my Video Agent for TikTok. When I say 'week plan', give me 7 video ideas based on what's working in my niche and my past numbers, each with a hook, a 30 second script and on screen text. When I say 'edit plan' and paste a script, give me the shot list, cut timings in seconds, captions on screen, zooms, B roll and sound. When I say 'post kit', write the caption, 4 hashtags and 3 cover text options. When I say 'review' and paste numbers, tell me what to double down on and what to cut. Keep my voice, no hype, and remind me to label realistic AI content."),
 sources=[("TikTok: About AI generated content","https://support.tiktok.com/en/using-tiktok/creating-videos/ai-generated-content"),("CapCut auto captions","https://www.capcut.com/resource/add-captions-with-ai")],
)
G["shop"] = dict(TT,
 kw="SHOP", title="Start selling on TikTok Shop", sub="Pick your path, pick a product that can actually make money, write a listing that follows the rules, and get creators to post it. Step by step with Claude.",
 time="About 1 hour to plan, then the TikTok approval", need="Claude, and for selling: a US address, ID and your tax info",
 why="TikTok Shop lets people buy without leaving the app. There are two ways in: sell your own products as a seller, or earn a commission promoting other people's products as an affiliate creator. Claude helps you pick the right path, do the math and write everything.",
 steps=[
  ("Pick your path", "Seller: you list products and get paid for orders. There's no follower minimum; in the US you need to be 18 or older, a US resident, with ID, the last 4 digits of your SSN or an ITIN (or your business documents), a US bank account, and a phone number and email not already used on another shop. Affiliate creator: you earn a commission on products you tag. In the US you can apply at around 1,000 followers and 18 or older. Under 5,000 followers you start in a trial period of at least 30 days, reported as up to 3 shoppable videos a day, 3 shoppable LIVEs a week, no campaigns, and only products from shops in good standing. Requirements change, so check the current rules in the app.", "Help me choose between becoming a TikTok Shop seller or an affiliate creator. About me: [followers, what I post, do I have a product or can I get one, budget, time per week]. Compare both for my situation: what I need to start, how I'd make money, the risks, and the first 3 steps for the path you recommend.", [("TikTok Shop Seller Center","https://seller-us.tiktok.com")]),
  ("Pick a product that can win", "The best TikTok products are easy to show working in a few seconds. Have Claude pressure test your ideas:", "I want to sell on TikTok Shop in [niche]. Give me 10 product ideas that are easy to demo in under 10 seconds, solve a clear problem, are light to ship, and could sell between $15 and $50. For each one: why it works on TikTok, what could go wrong (returns, competition, rules), and how I'd show it in a video. Flag anything that might be restricted, then check it yourself against TikTok Shop's Prohibited Products Policy before buying stock.", [("TikTok Shop Prohibited Products Policy","https://seller-us.tiktok.com/university/essay?knowledge_id=1399532709988097&lang=en")]),
  ("Do the math before you list", "TikTok takes a referral fee on every order (the rate depends on your category; check it in Seller Center), plus whatever commission you give creators, fulfillment and returns. Know your real profit first:", "Build me a TikTok Shop profit table for my product. Price: $[price]. Product cost: $[cost]. TikTok referral fee: [rate from Seller Center]%. Creator commission: [%]. Fulfillment and shipping per order: $[x]. Expected return rate: [%]. Free samples to creators: $[x] each. Show profit per order with and without a creator sale, my break even price, my break even ROAS if I run ads, and the price I'd need for a 30% margin.", []),
  ("Write a listing that sells and follows the rules", "Paste your product details and let Claude write a clear listing with no claims you can't back up:", "Write a TikTok Shop listing for: [product details, sizes, materials, what's in the box]. Give me a title under 100 characters, 5 benefit bullets, a short description, and 3 photo ideas. Only include claims I can prove. Avoid medical, guaranteed result or before and after promises. Flag anything that could break TikTok Shop rules.", []),
  ("Get creators to post it", "A big share of TikTok Shop sales come from creator videos and LIVEs. Set an open commission in Seller Center's Affiliate Center so any creator can pick up your product, then send personal invites to your top picks:", "Write a short message inviting TikTok creators in [niche] to promote my product [product] through TikTok Shop's affiliate program. Mention the commission ([%]), offer a free sample, and give 2 video ideas that fit their style. Keep it short and human, no pressure.", []),
  ("Show it every day, the right way", "Post product videos that show it working: problem then fix, a quick demo, 3 reasons, or a reply to a real comment. Use real demos with your hands, your face or your own real voice (not AI text to speech), with real movement on screen from the first seconds. TikTok Shop has daily limits on shoppable posts for US accounts. If you post 5 or more static or misleading shoppable videos (slideshows, text only, AI voice, showing one product but linking another) in 7 days, only 7 of your next videos keep their product links for the following week. Check the exact limits in the app. The free Video guide turns this into a weekly plan.", None, [("Free Video guide","https://autopilotoi.app/g/video/")]),
  ("Survive your first 30 days", "Every new shop starts in a probation period with a daily order cap and a listing cap that rise as you prove you're reliable. Once you have about 30 delivered orders, TikTok gives your shop a Shop Performance Score from 0 to 5 based on product satisfaction, shipping and customer service. Below 3.5 you can't run affiliate plans with creators, and below 3.0 your creator plans are removed, so protecting this score protects your sales. TikTok also tracks an Account Health Rating for policy violations: shops start at 200 points, at 150 you can't add new listings for 7 days, and at 0 the shop can be closed. Check both weekly in Seller Center. So: ship on time with valid tracking, never oversell, answer messages fast, and fix anything that causes returns or bad reviews. When you're ready for ads, GMV Max is the ad type TikTok uses for Shop; start only with a product that's already selling and a budget you can afford to lose.", "Make me a first 30 days plan for my new TikTok Shop selling [product]. I can ship within [x] days and spend $[x] on samples and ads. Include: a daily checklist to protect my Shop Performance Score and Account Health Rating (shipping, messages, returns, policy), how many videos to post and what kind, how many creators to contact per day, what to do if a video goes viral and I hit my daily order cap, and when it makes sense to test ads.", [("TikTok Shop Seller Center","https://seller-us.tiktok.com")]),
 ],
 warn=["TikTok Shop fees, shipping options, posting limits and eligibility change often. Always confirm in Seller Center and TikTok Shop Academy before you price or launch.","Don't chase a viral spike you can't ship. Late or cancelled orders hurt your Shop Performance Score and your probation limits.","No claims you can't prove: no cures, no guaranteed results, no fake reviews.","Affiliates must clearly disclose that they earn a commission. Use TikTok's disclosure setting and say it in the video too."],
 agent=dict(name="Shop Agent", what="A Claude Project that researches products, checks your profit before you list, writes your listings and keeps your creator outreach organized.",
  setup=["Create a Claude Project named Shop Agent.","Paste the instructions below.","Add a note with your niche, budget, current products and your category's referral fee from Seller Center.","Type: find products, check profit, write listing, or creator outreach."],
  instr="You are my TikTok Shop Agent. When I say 'find products', suggest products for my niche that are easy to demo, light to ship and in my price range, with risks and video ideas. When I say 'check profit', build a profit table with my fee, commission, fulfillment and returns, and tell me my break even price. When I say 'write listing', write a compliant title, bullets and description with no claims I can't prove. When I say 'creator outreach', write personal invites and keep a tracker (creator, date, status, sample sent, posted). Always tell me to confirm fees and rules in Seller Center."),
 sources=[("TikTok Shop Seller Center","https://seller-us.tiktok.com"),("FTC: Disclosures 101 for social media influencers","https://www.ftc.gov/business-guidance/resources/disclosures-101-social-media-influencers")],
)
G["sell"] = dict(TT,
 kw="SELL", title="Build an AI sales agent for your TikTok", sub="Claude learns your product, writes the videos that sell it, scripts your LIVEs, and drafts a reply for every comment and DM in your voice.",
 time="About 45 minutes to set up", need="Your product details, your FAQs, and Claude",
 why="On TikTok, sales come from three things: videos that show the product working, LIVEs, and fast, helpful answers in the comments and DMs. Claude can prepare all three, so you spend less time in the app.",
 steps=[
  ("Give it your product brain", "Paste everything about your product into Claude once:", "Here is everything about my product: [what it is, price, sizes, what's included, shipping time, return policy, who it's for, the questions people always ask, and why people hesitate]. Turn this into a one page sales sheet: the main benefit in one line, the top 5 questions with short answers, the top 3 objections with honest replies, and who it's NOT for.", []),
  ("Make videos that sell without feeling like ads", "Have Claude write a week of product videos in the formats that convert on TikTok. Film real demos with your hands, your face or your own real voice (not AI text to speech): TikTok Shop can switch off product links for accounts that post repeated static or not interactive shoppable videos:", "Using my sales sheet, write 5 TikTok scripts under 25 seconds: 1) the problem, then the product fixing it, 2) a fast demo, 3) three reasons people love it, 4) a reply to a real comment: [paste comment], 5) what's in the box. Each with a 2 second hook and on screen text. Honest, no hype, no claims I can't prove.", []),
  ("Script your LIVE", "LIVEs sell because people can ask questions in real time. Going LIVE usually needs about 1,000 followers, and you must be 18 to sell. In shopping LIVEs everything you say must be live: no AI voices, no recorded audio, and still images can't cover most of the screen. Go in with a plan:", "Write a 30 minute TikTok LIVE plan for selling [product]. Include: a 60 second intro that tells people why to stay, when to pin the product, 3 demos, answers to the top questions from my sales sheet, a moment every 10 minutes to welcome new viewers and recap the offer, and a closing. Keep it natural, and remind me to mention if I earn a commission.", []),
  ("Answer every comment and DM", "Copy a batch of comments or DMs into Claude and get replies in your voice, ready to paste. First remove buyer names, addresses, phone numbers and order numbers, and never contact buyers outside TikTok:", "Here are new comments and DMs: [paste]. Using my sales sheet, draft a short, friendly reply to each in my voice. Answer the actual question, link to the product only when it helps, and flag any message that needs me personally (complaints, refunds, custom orders).", []),
  ("Follow up after the sale", "Reviews from real buyers bring the next buyers. Send the same message to every buyer, once, through TikTok Shop messages. TikTok Shop bans asking only happy buyers, asking more than once per order, and review request cards in the package:", "Write a short thank you message for everyone who bought [product], with one tip to get the most out of it and one polite ask to leave an honest review. It goes to every buyer, once, through TikTok Shop messages. No reward, no pressure, and nothing that asks only for positive reviews.", []),
  ("Learn from the numbers every week", "Paste your weekly sales and video numbers so the agent knows what to repeat:", "Here are this week's numbers: [each video or LIVE: views, clicks, orders, top comments]. Tell me which video style and which message sold the most, what questions keep coming up, and what to post next week.", []),
 ],
 warn=["Never post fake reviews or testimonials. The FTC bans fake reviews and rewards tied to positive reviews, and TikTok Shop bans any reward for reviews outside its official program.","If you earn a commission or got the product free, disclose it clearly.","Read every reply before you send it. You're responsible for what your account says."],
 agent=dict(name="Sales Agent", what="A Claude Project that knows your product inside out and drafts your videos, LIVE plans, comment replies and follow ups in your voice.",
  setup=["Create a Claude Project named Sales Agent.","Paste the instructions below.","Upload your sales sheet and 5 examples of how you talk (old captions or messages).","Type: videos, live plan, replies (then paste comments), or weekly review."],
  instr="You are my Sales Agent for TikTok. Use my sales sheet and my voice. When I say 'videos', write 5 short product scripts in proven formats with hooks and on screen text. When I say 'live plan', write a 30 minute LIVE run of show. When I say 'replies' and paste comments or DMs, draft a helpful reply for each and flag anything that needs me. When I say 'weekly review' and paste numbers, tell me what sold and what to post next. Never invent claims, reviews or results, and always remind me to disclose commissions."),
 sources=[("FTC: Disclosures 101 for social media influencers","https://www.ftc.gov/business-guidance/resources/disclosures-101-social-media-influencers"),("FTC: rule banning fake reviews","https://www.ftc.gov/news-events/news/press-releases/2024/08/federal-trade-commission-announces-final-rule-banning-fake-reviews-testimonials")],
)

# DRAFT (Oct 31 2026 factory run): improved REFUND guide. Not linked anywhere. On Seb's APPROVED,
# copy these fields over G["refund"] and delete this entry. Sources opened Oct 31 2026: DOT refunds page
# (updated Nov 7 2025), FTC "Using Credit Cards and Disputing Charges", CFPB ask-cfpb 61 and 1017.
G["refund-v2"] = dict(
 draft=True, base="refund",
 kw="REFUND", bundle=False, title="Get your money back", sub="Canceled flights, double charges, things that never arrived. You often have a legal right to a refund. Here's how to claim it with Claude.",
 time="About 10 minutes per refund", need="The receipt or booking, any emails, and Claude",
 why="Companies don't always refund you on their own. A short written request that names the rule is easy for them to approve, and it starts the paper trail you need if you have to escalate.",
 steps=[
  ("Find your refunds", "Have Claude scan your recent statements and emails for money you may be owed. Black out full card and account numbers first; the last 4 digits are enough:", "I uploaded my last 3 months of card statements. Find anything that could be refundable: duplicate charges, charges for things I canceled or returned, orders that may not have arrived, canceled or changed flights, hotel or rental fees, price increases, and fees I didn't agree to. Make a table: merchant, date, amount, the statement it first appeared on, why it might be refundable, and what proof I should find. Ask me before assuming.", []),
  ("Flights: know the rule", "Under U.S. Department of Transportation rules, if an airline cancels your flight for any reason, or makes a significant change, and you turn down the alternatives (a new flight, a credit or a voucher), you're owed your money back, not just a voucher. Significant means departing or arriving 3+ hours off on a domestic trip or 6+ hours off on an international one, a different airport, extra connections, or a downgrade to a lower cabin. If you bought from the airline, the refund should be automatic once you decline. Card refunds are due within 7 business days, other payment methods take longer. If you take the changed flight, you generally can't get the ticket refunded.", None, [("DOT: refunds","https://www.transportation.gov/individuals/aviation-consumer-protection/refunds")]),
  ("Ask the company, but watch the clock", "For a card charge, your 60 day dispute window (step 4) keeps running while you wait on the company. The FTC suggests telling your card company early so you don't miss it. Then paste your booking or receipt details and use this:", "Write a refund request to [company]. Order or booking number: [number]. What happened: [facts and dates]. What I want: a refund of $[amount] to my original payment method, not a credit or voucher. If it applies, mention my rights [for flights: the DOT refund rule for canceled or significantly changed flights / for card purchases: my right to dispute billing errors with my card issuer]. Keep it short, specific and polite, list what I'm attaching, and ask for a reply within 7 days.", []),
  ("Credit card: dispute it in writing", "If the company won't fix a double charge, a charge for something you returned, or an order that never arrived as agreed, call your card company, then send a written billing error notice. Federal law gives you this right, but only if the letter reaches the issuer within 60 days after the first statement with the charge was sent to you. Mail it to the billing inquiries address on your statement, not the payment address. Certified mail with a return receipt gives you proof. The issuer must confirm in writing within 30 days and resolve it within 90. You can hold off paying the disputed amount while they investigate; keep paying the rest.", "Write a billing error letter to my credit card issuer under the Fair Credit Billing Act. My name and address: [ ]. Card: ending in [last 4]. The charge: [merchant, date, amount], first shown on my statement dated [date]. What is wrong: [billed twice / returned on (date) / never delivered / not as agreed]. What I did with the merchant: [dates and their answers]. Ask them to remove the charge and any related fees and to confirm in writing. List the copies I'm enclosing (never originals). Plain and polite, under one page. Then tell me the date 60 days after my statement date so I know my deadline.", [("FTC: disputing charges","https://consumer.ftc.gov/articles/using-credit-cards-and-disputing-charges"),("FTC: sample letter","https://consumer.ftc.gov/articles/sample-letter-disputing-credit-and-debit-card-charges")]),
  ("Escalate if they say no", "For airlines, file a complaint with DOT. For a bank or card company that won't handle your dispute properly, you can submit a complaint to the CFPB. Have Claude turn your notes into a short, dated timeline first; complaints with clear dates are easier to act on:", "Turn these notes into a dated timeline for a complaint: [paste emails, dates, reference numbers]. One line per event: date, who, what happened. Then write a 5 sentence complaint summary and the outcome I'm asking for. Facts only, no guesses.", [("DOT: file an air travel complaint","https://www.transportation.gov/airconsumer/file-consumer-complaint"),("CFPB: submit a complaint","https://www.consumerfinance.gov/complaint/")]),
  ("Keep a paper trail", "Save every email, screenshot, reference number and the certified mail receipt in one folder. Paste new replies into the same Claude chat so the timeline stays current.", None, []),
 ],
 warn=["Claude helps you write the request. The company, the DOT or your card issuer decides the outcome.",
  "Only dispute charges that are actually wrong. A dispute isn't a way to get out of a purchase you agreed to.",
  "Debit cards work differently. For a debit or bank charge you didn't authorize, tell your bank within 60 days of the statement it appeared on; waiting longer can leave you paying for it. For other debit problems, ask your bank how it handles disputes.",
  "Phone calls don't protect your credit card dispute rights on their own. Send the written notice too, and keep a copy."],
 agent=G["refund"]["agent"] | dict(instr="You are my Refund Agent. When I say 'get my money back', read what I upload, tell me if I likely have a right to a refund and why, then write the request ready for me to review and send. If the merchant says no on a credit card charge, write a Fair Credit Billing Act billing error letter for the billing inquiries address. When I say 'refund scan', check my statements for duplicate charges, canceled services still billing, and fees I didn't agree to. Keep a log of every claim (company, amount, statement date, date sent, deadline, status) and remind me of the next step and any deadline, like the 60 day written dispute window. Never invent facts or promise an outcome. Keep it short."),
 sources=[("DOT: airline refunds","https://www.transportation.gov/individuals/aviation-consumer-protection/refunds"),("FTC: using credit cards and disputing charges","https://consumer.ftc.gov/articles/using-credit-cards-and-disputing-charges"),("CFPB: disputing a credit card charge","https://www.consumerfinance.gov/ask-cfpb/how-do-i-dispute-a-charge-on-my-credit-card-bill-en-61/"),("CFPB: unauthorized bank or debit transactions","https://www.consumerfinance.gov/ask-cfpb/how-do-i-get-my-money-back-after-i-discover-an-unauthorized-transaction-or-money-missing-from-my-bank-account-en-1017/")],
)
